import React, { useEffect, useState } from "react";
import axios from "axios";

export default function AnalyticsDashboard() {
  const [totalDeliveriesToday, setTotalDeliveriesToday] = useState(0);
  const [activeDrivers, setActiveDrivers] = useState(0);
  const [successRate, setSuccessRate] = useState("0%");

  useEffect(() => {
    const fetchAnalytics = async () => {
      try {
        const deliveryRes = await axios.get("http://localhost:5000/api/delivery");
        const driverRes = await axios.get("http://localhost:5000/api/drivers");

        const today = new Date().toISOString().split("T")[0];

        const deliveriesToday = deliveryRes.data.filter((d: any) =>
          d.createdAt?.startsWith(today)
        );

        const delivered = deliveryRes.data.filter((d: any) => d.status === "Delivered");
        const total = deliveryRes.data.length;

        setTotalDeliveriesToday(deliveriesToday.length);
        setActiveDrivers(driverRes.data.filter((d: any) => d.isAvailable).length);
        setSuccessRate(total ? `${Math.round((delivered.length / total) * 100)}%` : "0%");
      } catch (error) {
        console.error("❌ Failed to fetch analytics", error);
      }
    };

    fetchAnalytics();
  }, []);

  return (
    <div style={{ padding: "20px" }}>
      <h2>📊 Analytics Dashboard</h2>
      <div style={card}>
        <h3>📦 Deliveries Today: {totalDeliveriesToday}</h3>
        <h3>🚚 Active Drivers: {activeDrivers}</h3>
        <h3>✅ Success Rate: {successRate}</h3>
      </div>
    </div>
  );
}

const card = {
  marginTop: "20px",
  padding: "20px",
  border: "1px solid #ccc",
  borderRadius: "10px",
  backgroundColor: "#f9f9f9",
};
